    { type: 'mc', page: 32, q: ['ما وجه ترجيح أن القرء الحيض في المذكرات؟', 'Waarom heeft "qurʾ is menstruatie" in de notities de voorkeur?'], options: [['لأن العدة تتعلق بخروج شيء تُعلم به براءة الرحم', 'لأنه أطول مدة', 'لأنه قول أكثر اللغويين', 'لأنه أيسر على المرأة'], ['omdat de wachttijd hangt aan iets waardoor blijkt dat de baarmoeder leeg is', 'omdat het langer duurt', 'omdat de meeste taalgeleerden het zeggen', 'omdat het makkelijker is voor de vrouw']], answer: 0, explain: ['وهذا لا يتحقق إلا بخروج الحيض.', 'En dat gebeurt alleen door menstruatiebloed.'] },
    { type: 'tf', page: 33, q: ['يُستدل بآية الطلاق 4 على أن الحيض أصل والأشهر بدل عند تعذّره.', 'Aṭ-Ṭalāq 4 bewijst dat menstruatie de basis is en maanden de vervanging als die er niet is.'], answer: 0, explain: ['نقلهن الله عند عدم الحيض إلى الاعتداد بالأشهر، فدلّ على أن الأصل الحيض.', 'Zonder menstruatie gaan zij over op maanden; dus is menstruatie de basis.'] },
    { type: 'tf', page: 33, q: ['كان الطلاق في الجاهلية محدوداً بثلاث.', 'In de jāhiliyya was echtscheiding beperkt tot drie keer.'], answer: 1, explain: ['بل كان بلا حدّ، مهملاً كسائر أفعالها، فشرع الله أمده.', 'Nee, het was onbegrensd en ongeregeld; Allah stelde er een limiet aan.'] },
    { type: 'mc', page: 34, q: ['ما المراد بـ﴿الطلاق مرتان﴾؟', 'Wat is bedoeld met ﴿echtscheiding is twee keer﴾?'], options: [['الطلاق الذي تحصل به الرجعة مرتان', 'لا يقع الطلاق إلا مرتين في العمر', 'يجب أن يطلّق مرتين معاً', 'الطلاق الثالث لا يقع'], ['de echtscheiding met terugname is twee keer', 'men kan maar twee keer in het leven scheiden', 'men moet twee keer tegelijk scheiden', 'een derde scheiding telt niet']], answer: 0, explain: ['فأخبر الله أن الطلاق الذي تحصل به الرجعة مرتان، وما فوق ذلك فلا رجعة فيه.', 'De scheiding met terugname is twee keer; daarboven geen terugname.'] },
    { type: 'tf', page: 34, q: ['من التسريح بإحسان ألا يأخذ الزوج على فراقه لها شيئاً من مالها.', 'Goed laten gaan houdt in dat de man voor de scheiding niets van haar geld neemt.'], answer: 0, explain: ['لأنه ظلم وأخذ للمال في غير مقابلة بشيء.', 'Want dat is onrecht en nemen zonder tegenprestatie.'] },
    { type: 'mc', page: 34, q: ['ما المراد بـ﴿إلا أن يخافا ألا يقيما حدود الله﴾ عند ابن العربي؟', 'Wat betekent ﴿behalve als beiden vrezen de grenzen van Allah niet te handhaven﴾ volgens Ibn al-ʿArabī?'], options: [['أن يظن كل واحد منهما ألا يقيم حق النكاح لصاحبه', 'أن يخافا الحدود الشرعية كحد الزنا', 'أن يخاف الولي من الزوج', 'أن يخافا الفقر'], ['ieder denkt dat hij de huwelijksrechten tegenover de ander niet zal nakomen', 'zij vrezen de lijfstraffen zoals die voor ontucht', 'de walī vreest de man', 'zij vrezen armoede']], answer: 0, explain: ['قال: وفي ذلك تأويلات كلها أباطيل، وإنما المراد به أن يظن كل واحد منهما ألا يقيم حق النكاح لصاحبه.', 'Hij zegt: andere uitleggingen zijn allemaal onjuist; bedoeld is dat ieder denkt de huwelijksrechten niet na te komen.'] },
    { type: 'tf', page: 35, q: ['قالت امرأة ثابت بن قيس إنها تعيب عليه في خلقه ودينه.', 'De vrouw van Thābit ibn Qays zei dat zij iets aan te merken had op zijn karakter en godsdienst.'], answer: 1, explain: ['قالت: ما أعيب عليه في خلق ولا دين، ولكني أكره الكفر في الإسلام.', 'Zij zei: ik heb níets aan te merken op zijn karakter of godsdienst, maar ik haat kufr in de islam.'] },
    { type: 'mc', page: 35, q: ['ما المراد بالكفر في قول امرأة ثابت: «أكره الكفر في الإسلام»؟', 'Wat bedoelde de vrouw van Thābit met kufr in «ik haat kufr in de islam»?'], options: [['كفران العشير', 'الردة عن الإسلام', 'الشرك بالله', 'كفر النعمة في المال'], ['ondankbaarheid jegens de echtgenoot', 'afvalligheid van de islam', 'shirk', 'ondankbaarheid voor rijkdom']], answer: 0, explain: ['تخشى أن يؤدي بها النفور منه إلى كفران العشير.', 'Zij vreesde dat haar afkeer zou leiden tot ondankbaarheid jegens haar man.'] },
    { type: 'mc', page: 35, q: ['بماذا أمر النبي ﷺ ثابت بن قيس؟', 'Wat droeg de Profeet ﷺ Thābit ibn Qays op?'], options: [['اقبل الحديقة وطلّقها تطليقة', 'طلّقها ثلاثاً', 'أمسكها بمعروف', 'لا تأخذ منها شيئاً'], ['neem de tuin aan en scheid één keer van haar', 'scheid drie keer van haar', 'behoud haar op behoorlijke wijze', 'neem niets van haar aan']], answer: 0, explain: ['قال: «اقبل الحديقة وطلّقها تطليقة».', 'Hij zei: «Neem de tuin aan en scheid één keer van haar.»'] },
    { type: 'mc', page: 35, q: ['من قال إن المطلقة ثلاثاً تحلّ للأول بمجرد عقد الثاني؟', 'Wie zei dat de drievoudig gescheiden vrouw door alleen de akte met de tweede weer toegestaan wordt?'], options: [['سعيد بن المسيب', 'ابن العربي', 'مالك', 'ابن عباس'], ['Saʿīd ibn al-Musayyib', 'Ibn al-ʿArabī', 'Mālik', 'Ibn ʿAbbās']], answer: 0, explain: ['قال سعيد بن المسيب ذلك لظاهر الآية، وردّه ابن العربي.', 'Saʿīd ibn al-Musayyib, op grond van de bewoording; Ibn al-ʿArabī weerlegt hem.'] },
    { type: 'tf', page: 36, q: ['عند ابن العربي: القرآن اقتضى العقد وزادت السنة الجماع.', 'Volgens Ibn al-ʿArabī bedoelde de Koran de akte en voegde de Sunna gemeenschap toe.'], answer: 1, explain: ['قال: لا يُقال ذلك، إنما يُقال: إن السنة أثبتت المراد منها.', 'Hij zegt: dat zegt men niet; men zegt dat de Sunna vastlegde wat bedoeld is.'] },
    { type: 'mc', page: 36, q: ['ما الذي يدل عليه قوله ﷺ: «حتى تذوقي عسيلته ويذوق عسيلتك»؟', 'Wat toont «tot je zijn ʿusayla proeft en hij de jouwe»?'], options: [['أنه لا بد أن يحصل جماع بينهما', 'أنه يكفي العقد', 'أنه يكفي الخلوة', 'أنه يجب المهر كاملاً'], ['dat er gemeenschap tussen hen moet zijn', 'dat de akte genoeg is', 'dat alleen samenzijn genoeg is', 'dat de volledige bruidsgave verplicht is']], answer: 0, explain: ['لا بد أن يحصل جماع بينهما.', 'Er moet gemeenschap tussen hen plaatsvinden.'] },
    { type: 'tf', page: 36, q: ['قال ابن العربي إن البلوغ في ﴿فبلغن أجلهن﴾ في آية العضل حقيقة لا مجاز فيه.', 'Ibn al-ʿArabī zegt dat bereiken in ﴿en zij hun termijn bereikt hebben﴾ in het ʿaḍl-vers letterlijk is.'], answer: 0, explain: ['لأن ﴿فلا تعضلوهن﴾ بيّن أن العدة انقضت وسقط حق الزوج من الرجعة.', 'Want ﴿verhinder hen niet﴾ toont dat de wachttijd voorbij is en het terugnamerecht vervallen.'] },
    { type: 'mc', page: 37, q: ['من خالفه ابن العربي في أن المرأة لا حق لها في مباشرة النكاح؟', 'Tegen wie gaat Ibn al-ʿArabī in met "de vrouw mag het huwelijk niet zelf sluiten"?'], options: [['أبو حنيفة', 'الشافعي', 'مالك', 'سعيد بن المسيب'], ['Abū Ḥanīfa', 'ash-Shāfiʿī', 'Mālik', 'Saʿīd ibn al-Musayyib']], answer: 0, explain: ['قال: وإنما هو حق الولي، خلافاً لأبي حنيفة.', 'Hij zegt: het is het recht van de walī, tegen Abū Ḥanīfa in.'] },
    { type: 'mc', page: 37, q: ['في من نزلت آية العضل كما عند البخاري؟', 'Over wie kwam het ʿaḍl-vers volgens al-Bukhārī?'], options: [['معقل بن يسار وأخته', 'ثابت بن قيس وامرأته', 'رفاعة وامرأته', 'كعب بن عجرة'], ['Maʿqil ibn Yasār en zijn zus', 'Thābit ibn Qays en zijn vrouw', 'Rifāʿa en zijn vrouw', 'Kaʿb ibn ʿUjra']], answer: 0, explain: ['أبى معقل أن يزوّج أخته من زوجها السابق، فنزلت الآية.', 'Maʿqil weigerde zijn zus opnieuw aan haar vroegere man te geven; toen kwam het vers.'] },
    { type: 'tf', page: 37, q: ['يرى المحشّي أن النهي عن العضل خاص بمن تريد الرجوع إلى زوجها السابق.', 'Volgens de leraar geldt het verbod op ʿaḍl alleen voor wie terug wil naar haar vorige man.'], answer: 1, explain: ['قال: وهذا يجري على من تريد الرجوع إلى زوجها السابق ومن تريد لأول مرة.', 'Hij zegt: het geldt voor wie terug wil naar haar vorige man én voor wie voor het eerst trouwt.'] },
    { type: 'tf', page: 37, q: ['استدل ابن العربي بأنه لو لم يكن لمعقل حق لقال الله لنبيّه: لا كلام لمعقل في ذلك.', 'Ibn al-ʿArabī redeneert: had Maʿqil geen recht, dan had Allah tegen Zijn Profeet gezegd dat Maʿqil er niets over te zeggen heeft.'], answer: 0, explain: ['هذا نص استدلاله في المذكرات.', 'Zo staat zijn redenering in de notities.'] }
